code.C:
#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long max_v, x; scanf("%lld", &x);
    max_v = x; int count = 1;
    for (int i = 1; i < n; i++) {
        scanf("%lld", &x);
        if (x > max_v) { count++; max_v = x; }
    }
    printf("%d\n", count);
    return 0;
}

