code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long maxV = sc.nextLong();
            int count = 1;
            for (int i = 1; i < n; i++) {
                long x = sc.nextLong();
                if (x > maxV) { count++; maxV = x; }
            }
            System.out.println(count);
        }
    }
}

