const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    let maxV = -Infinity, count = 0;
    for (let i = 1; i <= n; i++) {
        const val = Number(toks[i]);
        if (val > maxV) { count++; maxV = val; }
    }
    console.log(count);
}
main();

